type Prove_Options is record
   Jobs              : Integer := -1;
   Level             : Integer := -1;
   Timeout           : Integer := -1;
   Steps             : Integer := -1;
   Memlimit          : Integer := -1;
   Force             : Boolean := False;
   No_Loop_Unrolling : Boolean := False;
   No_Inlining       : Boolean := False;
   Cache             : Boolean := True;
end record;

